import java.util.Scanner;
public class JIfElseNumSign1 {
	public static void main(String[] args) {
		//Paso 1: Leer el entero 
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese un entero: ");
		int num = scan.nextInt();		
		scan.close();
		//Paso 2: Determinar si el entero es positivo, negativo o cero
		if (num > 0) {
			System.out.println("El entero es positivo.");
		} else if (num < 0) {
			System.out.println("El entero es negativo.");
		} else {
			System.out.println("El entero es cero.");
		}
	}
}

